from hermes_tools import terminal, shell_quote
code='''D3=[(0,6),(0,10),(1,1),(4,9),(5,1),(6,8),(8,0),(8,3),(9,8),(10,5)]
T=[(0,10),(1,1),(1,6),(3,1),(5,3),(5,8),(8,0),(9,1),(9,10),(10,6)]
base=[(r-4,c-4) for r,c in D3]
fs={'id':lambda r,c:(r,c),'rot90':lambda r,c:(c,-r),'rot180':lambda r,c:(-r,-c),'rot270':lambda r,c:(-c,r),'flipH':lambda r,c:(r,-c),'flipV':lambda r,c:(-r,c),'diag':lambda r,c:(c,r),'anti':lambda r,c:(-c,-r)}
for n,f in fs.items():
 m={(5+f(r,c)[0],6+f(r,c)[1]) for r,c in base if 0<=5+f(r,c)[0]<=10 and 0<=6+f(r,c)[1]<=10}
 print(n,len(m),len(m&set(T)),sorted(set(T)-m))'''
