 ('identity',lambda r,c:(r,c)),('rot90',lambda r,c:(c,10-r)),('rot180',lambda r,c:(10-r,10-c)),('rot270',lambda r,c:(10-c,r)),
 ('reflect_lr',lambda r,c:(r,10-c)),('reflect_ud',lambda r,c:(10-r,c)),('reflect_diag',lambda r,c:(c,r)),('reflect_anti',lambda r,c:(10-c,10-r))]:
 p={f(r,c) for r,c in demo}
 for dr in range(-10,11):
  for dc in range(-10,11):
   q={(r+dr,c+dc) for r,c in p}
   if q==test: maps.append((name,dr,dc))
print('matches',maps)
# best overlap under transforms + allowable translation, max intersection
best=[]
for name,f in [
